    "landing.faq_title": "किसानों और खरीदारों के प्रश्न",
    "landing.faq_desc": "हमारी टीम तुरंत सहायता प्रदान करती है।",
    "landing.faq1_q": "क्या खेत में इंटरनेट की आवश्यकता है?",
    "landing.faq1_a": "नहीं। गेटवे और कंट्रोलर ऑफ़लाइन काम करते हैं और नेटवर्क मिलने पर सिंक होते हैं।",
    "landing.faq2_q": "सेंसर किट की कीमत क्या है?",
    "landing.faq2_a": "छोटे और मध्यम खेतों के लिए किफायती किट और मासिक प्लान उपलब्ध हैं।",
    "landing.faq3_q": "कटाई के पूर्वानुमान कितने सटीक हैं?",
    "landing.faq3_a": "मृदा इतिहास और मौसम मॉडल मिलाकर उच्च सटीकता प्रदान की जाती है।",
    "landing.faq4_q": "क्या खरीदार किसानों से सीधे संपर्क कर सकते हैं?",
    "landing.faq4_a": "खरीदार फार्मगार्ड के माध्यम से सुरक्षित खरीद अनुरोध भेजते हैं।",
    "landing.faq5_q": "कौन सी भाषाएं समर्थित हैं?",
    "landing.faq5_a": "अंग्रेजी, हिंदी, तमिल, कन्नड़, मलयालम और तेलुगु।",
    "landing.faq6_q": "क्या मेरे खेत का डेटा सुरक्षित है?",
    "landing.faq6_a": "किसान अपने डेटा के स्वामी हैं। केवल एकत्रित जानकारी साझा की जाती है।",
    "landing.cta_title": "अपने खेत को ऑनलाइन लाएं",
    "landing.cta_desc": "दो मिनट में खाता बनाएं और अपना कार्यक्षेत्र चुनें।",
