    "landing.t1_quote": "ನೀರಾವರಿ ಸಮಯವನ್ನು ಊಹಿಸುವುದನ್ನು ನಿಲ್ಲಿಸಿದೆ. ಪಂಪ್ ತಾನೇ ನಡೆಯುತ್ತದೆ, ಡೀಸೆಲ್ ಖರ್ಚು ಕಡಿಮೆಯಾಗಿದೆ.",
    "landing.t1_name": "ಆರ್. ಸೆಲ್ವರಾಜ್",
    "landing.t1_role": "ಭತ್ತ ಬೆಳೆಗಾರ, ತಂಜಾವೂರು",
    "landing.t2_quote": "ನಾವು ಟೊಮೆಟೊ ಖರೀದಿಯನ್ನು 6 ವಾರಗಳ ಮುಂಚೆಯೇ ಯೋಜಿಸುತ್ತೇವೆ. ಗುಣಮಟ್ಟದ ಸ್ಕೋರ್ ತುಂಬಾ ನಿಖರವಾಗಿದೆ.",
    "landing.t2_name": "ಪ್ರಿಯಾ ನಾಯರ್",
    "landing.t2_role": "ಖರೀದಿ ಮುಖ್ಯಸ್ಥರು, ಸನ್‌ರೈಸ್ ಫುಡ್ಸ್",
    "landing.t3_quote": "ನಮ್ಮ ಸೊಸೈಟಿಯ 60 ಫಾರ್ಮ್‌ಗಳು ಫಾರ್ಮ್‌ಗಾರ್ಡ್ ಬಳಸುತ್ತಿವೆ. ಖರೀದಿದಾರರು ನಮ್ಮ ಡೇಟಾವನ್ನು ನಂಬುತ್ತಾರೆ.",
    "landing.t3_name": "ಕೆ. ಪ್ರಕಾಶ್",
    "landing.t3_role": "FPO ಕಾರ್ಯದರ್ಶಿ, ಮೈಸೂರು",
    "landing.faq_eyebrow": "FAQ",
    "landing.faq_title": "ಸಾಮಾನ್ಯವಾಗಿ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳು",
    "landing.faq_desc": "ನಮ್ಮ ತಂಡ ಶೀಘ್ರದಲ್ಲೇ ಪ್ರತಿಕ್ರಿಯಿಸುತ್ತದೆ.",
    "landing.faq1_q": "ಜಮೀನಿನಲ್ಲಿ ಇಂಟರ್ನೆಟ್ ಅಗತ್ಯವಿದೆಯೇ?",
    "landing.faq1_a": "ಇಲ್ಲ. ಗೇಟ್‌ವೇ ಆಫ್‌ಲೈನ್‌ನಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ ಮತ್ತು ನೆಟ್‌ವರ್ಕ್ ಸಿಕ್ಕಾಗ ಸಿಂಕ್ ಆಗುತ್ತದೆ.",
    "landing.faq2_q": "ಸಂವೇದಕ ಕಿಟ್ ಬೆಲೆ ಎಷ್ಟು?",
    "landing.faq2_a": "ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಜಮೀನುಗಳಿಗೆ ಕೈಗೆಟುಕುವ ಯೋಜನೆಗಳು ಲಭ್ಯವಿವೆ.",
    "landing.faq3_q": "ಕೊಯ್ಲು ಮುನ್ಸೂಚನೆಗಳು ಎಷ್ಟು ನಿಖರವಾಗಿವೆ?",
    "landing.faq3_a": "ಮಣ್ಣಿನ ಇತಿಹಾಸ ಮತ್ತು ಹವಾಮಾನ ಡೇಟಾ ಆಧಾರದ ಮೇಲೆ ನಿಖರ ಮುನ್ಸೂಚನೆ ನೀಡಲಾಗುತ್ತದೆ.",
    "landing.faq4_q": "ಖರೀದಿದಾರರು ನೇರವಾಗಿ ಸಂಪರ್ಕಿಸಬಹುದೇ?",
    "landing.faq4_a": "ಖರೀದಿದಾರರು ಫಾರ್ಮ್‌ಗಾರ್ಡ್ ಮೂಲಕ ಖರೀದಿ ವಿನಂತಿಗಳನ್ನು ಕಳುಹಿಸುತ್ತಾರೆ.",
    "landing.faq5_q": "ಯಾವ ಭಾಷೆಗಳು ಲಭ್ಯವಿವೆ?",
    "landing.faq5_a": "ಇಂಗ್ಲಿಷ್, ಹಿಂದಿ, ತಮಿಳು, ಕನ್ನಡ, ಮಲಯಾಳಂ ಮತ್ತು ತೆಲುಗು.",
    "landing.faq6_q": "ನನ್ನ ಫಾರ್ಮ್ ಡೇಟಾ ಸುರಕ್ಷಿತವಾಗಿದೆಯೇ?",
    "landing.faq6_a": "ರೈತರೇ ತಮ್ಮ ಡೇಟಾದ ಮಾಲೀಕರು. ಒಟ್ಟು ಮಾಹಿತಿ ಮಾತ್ರ ಹಂಚಿಕೊಳ್ಳಲಾಗುತ್ತದೆ.",
