    "landing.t1_quote": "ഞാൻ ജലസേചന സമയം ഊഹിക്കുന്നത് നിർത്തി. പമ്പ് സ്വയം പ്രവർത്തിക്കുകയും ഡീസൽ ചെലവ് കുറയുകയും ചെയ്തു.",
    "landing.t1_name": "ആർ. സെൽവരാജ്",
    "landing.t1_role": "നെൽ കർഷകൻ, തഞ്ചാവൂർ",
    "landing.t2_quote": "ഞങ്ങൾ തക്കാളി സംഭരണം ആറാഴ്ച മുമ്പേ പ്ലാൻ ചെയ്യുന്നു.",
    "landing.t2_name": "പ്രിയ നായർ",
    "landing.t2_role": "പ്രൊക്യുർമെന്റ് ഹെഡ്, സൺറൈസ് ഫുഡ്സ്",
    "landing.t3_quote": "ഞങ്ങളുടെ സൊസൈറ്റിയിലെ 60 ഫാമുകൾ ഫാംഗാർഡ് ഉപയോഗിക്കുന്നു.",
    "landing.t3_name": "കെ. പ്രകാശ്",
    "landing.t3_role": "FPO സെക്രട്ടറി, മൈസൂരു",
    "landing.faq_eyebrow": "ചോദ്യോത്തരങ്ങൾ",
    "landing.faq_title": "കർഷകരും വാങ്ങുന്നവരും ചോദിക്കുന്ന ചോദ്യങ്ങൾ",
    "landing.faq_desc": "ഞങ്ങളുടെ ടീം ഉടൻ മറുപടി നൽകുന്നതാണ്.",
    "landing.faq1_q": "ഫാമിൽ ഇന്റർനെറ്റ് ആവശ്യമുണ്ടോ?",
    "landing.faq1_a": "ഇല്ല. ഉപകരണം ഓഫ്‌ലൈനായി പ്രവർത്തിക്കുകയും കണക്ഷൻ ലഭിക്കുമ്പോൾ സിങ്ക് ചെയ്യുകയും ചെയ്യും.",
    "landing.faq2_q": "സെൻസർ കിറ്റിന്റെ വില എത്രയാണ്?",
    "landing.faq2_a": "ചെറിയ ഫാമുകൾക്ക് അനുയോജ്യമായ കിറ്റുകൾ ലഭ്യമാണ്.",
    "landing.faq3_q": "വിളവെടുപ്പ് പ്രവചനങ്ങൾ എത്രത്തോളം കൃത്യമാണ്?",
    "landing.faq3_a": "മണ്ണ് വിവരങ്ങളും കാലാവസ്ഥയും സംയോജിപ്പിച്ച് പ്രവചനം നൽകുന്നു.",
    "landing.faq4_q": "വാങ്ങുന്നവർക്ക് നേരിട്ട് ബന്ധപ്പെടാമോ?",
    "landing.faq4_a": "വാങ്ങുന്നവർ ഫാംഗാർഡ് വഴി അഭ്യർത്ഥനകൾ അയക്കുന്നു.",
    "landing.faq5_q": "ഏതൊക്കെ ഭാഷകൾ പിന്തുണയ്ക്കുന്നു?",
    "landing.faq5_a": "ഇംഗ്ലീഷ്, ഹിന്ദി, തമിഴ്, കന്നഡ, മലയാളം, തെലുങ്ക്.",
    "landing.faq6_q": "ഫാം ഡാറ്റ സുരക്ഷിതമാണോ?",
    "landing.faq6_a": "കർഷകർക്കാണ് ഡാറ്റയുടെ ഉടമസ്ഥാവകാശം.",
