    "landing.testimonials_title": "రైతులు మరియు కొనుగోలుదారుల నమ్మకం",
    "landing.testimonials_desc": "దక్షిణ భారతదేశంలో రైతు గ్రూపులతో ఉపయోగించబడుతోంది.",
    "landing.t1_quote": "నేను నీటిపారుదల సమయాన్ని ఊహించడం మానేశాను. పంప్ ఆటోమేటిక్‌గా నడుస్తుంది మరియు డీజిల్ ఖర్చు తగ్గింది.",
