    "landing.t3_role": "FPO కార్యదర్శి, మైసూర్",
    "landing.faq_eyebrow": "తరచుగా అడిగే ప్రశ్నలు",
    "landing.faq_title": "రైతులు మరియు కొనుగోలుదారులు అడిగే ప్రశ్నలు",
    "landing.faq_desc": "మా టీమ్ వెంటనే స్పందిస్తుంది.",
    "landing.faq1_q": "పొలంలో ಇంటర్నెట్ అవసరమా?",
    "landing.faq1_a": "లేదు. పరికరం ఆఫ్‌లైన్‌లో పనిచేస్తుంది మరియు కనెక్షన్ వచ్చినప్పుడు సింక్ అవుతుంది.",
    "landing.faq2_q": "సెన్సార్ కిట్ ధర ఎంత?",
    "landing.faq2_a": "చిన్న పొలాలకు తగిన కిట్లు అందుబాటులో ఉన్నాయి.",
    "landing.faq3_q": "కోత అంచనాలు ఎంత కచ్చితమైనవి?",
    "landing.faq3_a": "నేల చరిత్ర మరియు వాతావరణ నమూనాలను కలిపి అంచనా ఇవ్వబడుతుంది.",
    "landing.faq4_q": "కొనుగోలుదారులు నేరుగా సంప్రదించవచ్చా?",
    "landing.faq4_a": "కొనుగోలుదారులు ఫార్మ్‌గార్డ్ ద్వారా అభ్యర్థనలు పంపుతారు.",
    "landing.faq5_q": "ఏ భాషలకు మద్దతు ఉంది?",
    "landing.faq5_a": "ఇంగ్లీష్, హిందీ, తమిళం, కన్నడ, మలయాళం మరియు తెలుగు.",
    "landing.faq6_q": "నా పొలం డేటా సురక్షితమేనా?",
    "landing.faq6_a": "రైతులదే డేటా యాజమాన్యం. మొత్తం వివరాలు మాత్రమే షేర్ చేయబడతాయి.",
    "landing.cta_title": "మీ పొలాన్ని ఆన్‌లైన్‌కి తీసుకెళ్లండి",
    "landing.cta_desc": "రెండు నిమిషాల్లో ఖాతా సృష్టించి మీ వర్క్‌స్పేస్‌ను ఎంచుకోండి.",
    "landing.cta_create": "ఖాతా సృష్టించండి",
